window.SCHOOL_LISTENING={"../assets/media/d71ce3a7747e8905a840d8a19a5d1a5f34b80f185177007e2fcf5a20963e3fa9.mp3":[{"id":"PPT_d71ce3a7747e8905","audioId":"PPT_d71ce3a7747e8905","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 63","duration":93.99,"cues":[{"start":0,"end":1.52,"text":"eight .three","coverage":1},{"start":3.42,"end":5.74,"text":"Welcome to Outer Space Today.","coverage":1},{"start":6.58,"end":6.98,"text":"Normally,","coverage":1},{"start":7.3,"end":10.12,"text":"this program discusses going into space.","coverage":1},{"start":10.76,"end":17.94,"text":"We talk about making long journeys into outer space, traveling well beyond our moon and the planets near us.","coverage":1},{"start":18.56,"end":19.04,"text":"However,","coverage":1},{"start":19.6,"end":20.66,"text":"in this episode,","coverage":1},{"start":21.12,"end":24.08,"text":"we're looking at the issue of space debris,","coverage":1},{"start":24.48,"end":25.44,"text":"or space junk.","coverage":1},{"start":26.06,"end":27.56,"text":"How did it first start?","coverage":1},{"start":28.2,"end":32.02,"text":"And what happens to all the things that people put into space?","coverage":1},{"start":33.4,"end":37.96,"text":"Humans first began to explore near space in 1957,","coverage":1},{"start":38.52,"end":41.74,"text":"when the Soviets sent the first human -made satellite,","coverage":1},{"start":42.18,"end":44.12,"text":"Sputnik one, into space.","coverage":1},{"start":44.9,"end":45.92,"text":"Three months later,","coverage":1},{"start":46.3,"end":49.64,"text":"the satellite stopped working and fell back to Earth.","coverage":1},{"start":50.26,"end":54.48,"text":"It didn't hit the ground because it burned up on the way to Earth.","coverage":1},{"start":55.24,"end":57.24,"text":"This was the first rubbish,","coverage":1},{"start":57.56,"end":58.26,"text":"or junk,","coverage":1},{"start":58.7,"end":59.5,"text":"from space.","coverage":1},{"start":60.38,"end":64.24,"text":"But when Karabi Sputnik one, or Sputnik four,","coverage":1},{"start":64.92,"end":67.06,"text":"fell to Earth in 1962,","coverage":1},{"start":67.98,"end":73.98,"text":"a piece of it fell in the middle of a street in the central part of the U .S.","coverage":1},{"start":74.58,"end":75.22,"text":"Fortunately,","coverage":1},{"start":75.86,"end":76.94,"text":"it didn't hit anybody.","coverage":1},{"start":77.78,"end":78.54,"text":"Nowadays,","coverage":1},{"start":79.32,"end":86.18,"text":"there are many pieces of space junk from many countries going around the Earth and falling to Earth.","coverage":1},{"start":86.82,"end":92.02,"text":"This has many effects on our space programs and causes space accidents.","coverage":1}],"file":"116b80c0ce26b9801010.js","track":0,"media":"../assets/media/d71ce3a7747e8905a840d8a19a5d1a5f34b80f185177007e2fcf5a20963e3fa9.mp3"}],"../assets/media/2b82f902d364dc2bc408836dfef919e3aba6fb90650eb39fc3c377fa1c0d6f92.mp3":[{"id":"PPT_2b82f902d364dc2b","audioId":"PPT_2b82f902d364dc2b","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 30","duration":60.87,"cues":[{"start":0,"end":1.38,"text":"Unit eight,","coverage":1},{"start":1.74,"end":3,"text":"eight .one","coverage":1},{"start":4.6,"end":8.7,"text":"one weather, weather","coverage":1},{"start":9.88,"end":10.88,"text":"two","coverage":1},{"start":11.48,"end":12.3,"text":"hour,","coverage":1},{"start":15.48,"end":17.78,"text":"three sun,","coverage":1},{"start":20.92,"end":23.3,"text":"four red,","coverage":1},{"start":24.08,"end":24.92,"text":"red","coverage":1},{"start":26.36,"end":27.44,"text":"five","coverage":1},{"start":28.04,"end":29.26,"text":"there,","coverage":1},{"start":33.6,"end":34.74,"text":"cent,","coverage":1},{"start":38.08,"end":42.04,"text":"seven eight eight","coverage":1},{"start":43.54,"end":46.12,"text":"eight mind,","coverage":1},{"start":49.4,"end":50.62,"text":"nine","coverage":1},{"start":51.16,"end":53.98,"text":"four four","coverage":1},{"start":55.14,"end":55.84,"text":"ten","coverage":1},{"start":56.64,"end":57.42,"text":"two","coverage":1},{"start":58.32,"end":59.1,"text":"two","coverage":1}],"file":"1681cb2ebce851dff29b.js","track":0,"media":"../assets/media/2b82f902d364dc2bc408836dfef919e3aba6fb90650eb39fc3c377fa1c0d6f92.mp3"}],"../assets/media/b3b6b705449e7b968bf2584acb0e86e26aaf134a19105e5e4251ddfea07fa0d0.mp3":[{"id":"PPT_b3b6b705449e7b96","audioId":"PPT_b3b6b705449e7b96","title":"Book 2 · Unit 8 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 92","duration":55.43,"cues":[{"start":0,"end":2,"text":"eight .five","coverage":1},{"start":3.76,"end":5.36,"text":"Part one","coverage":1},{"start":5.36,"end":5.98,"text":"Hello","coverage":1},{"start":5.98,"end":6.64,"text":"everyone.","coverage":1},{"start":7.34,"end":13.06,"text":"We'll begin today's discussion with a look at how to pay for space exploration.","coverage":1},{"start":13.98,"end":21.58,"text":"We'll also evaluate the benefits of space exploration and whether the money we spend is worth it.","coverage":1},{"start":22.32,"end":26.34,"text":"We will first look at the options for paying for space exploration.","coverage":1},{"start":26.96,"end":29.38,"text":"I have three experts with me today.","coverage":1},{"start":30.22,"end":30.98,"text":"Dorota Loy,","coverage":1},{"start":31.58,"end":34.14,"text":"an engineer from the Space Development Project.","coverage":1},{"start":34.84,"end":37.5,"text":"Raj Paddow, a researcher in economics.","coverage":1},{"start":38.5,"end":39.82,"text":"And Dr Jun Wu,","coverage":1},{"start":40.22,"end":42.08,"text":"who is a professor of astrophysics.","coverage":1},{"start":42.84,"end":53.68,"text":"Let me ask Dr Wu to start us off by giving us a little information about the impact of space exploration and the importance of spending money on it.","coverage":1}],"file":"30ba5c11b2a46e1e5ca1.js","track":0,"media":"../assets/media/b3b6b705449e7b968bf2584acb0e86e26aaf134a19105e5e4251ddfea07fa0d0.mp3"}],"../assets/media/8b6f885fff8f106631459efc6bce687b7fc6c80b2d00bdda398625b3efb920d2.mp3":[{"id":"PPT_8b6f885fff8f1066","audioId":"PPT_8b6f885fff8f1066","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 66","duration":183.54,"cues":[{"start":0,"end":1.82,"text":"eight .four","coverage":1},{"start":3.41,"end":5.74,"text":"Why is space junk a problem?","coverage":1},{"start":6.86,"end":7.22,"text":"Well,","coverage":1},{"start":7.58,"end":11.54,"text":"the pieces of space junk travel at extremely fast speeds,","coverage":1},{"start":12.06,"end":14.8,"text":"over 25 ,000 km per hour,","coverage":1},{"start":15.26,"end":19.3,"text":"and so they can cause very bad problems if they hit anything.","coverage":1},{"start":20.34,"end":20.82,"text":"NASA,","coverage":1},{"start":21.26,"end":21.96,"text":"the U .S.","coverage":1},{"start":22.1,"end":22.98,"text":"space agency,","coverage":1},{"start":23.6,"end":25.76,"text":"watches where the space junk is.","coverage":1},{"start":26.2,"end":28.32,"text":"The International Space Station,","coverage":1},{"start":28.7,"end":29.5,"text":"the ISS,","coverage":1},{"start":30.18,"end":37.46,"text":"can move out of the way of the space junk if they get a message to move at least five hours before an accident.","coverage":1},{"start":38.36,"end":42.32,"text":"Because people continue to send so many things into space,","coverage":1},{"start":42.84,"end":45.48,"text":"and this first started in 1957,","coverage":1},{"start":46.28,"end":50.66,"text":"there are now over 27 ,000 pieces of space junk.","coverage":1},{"start":51.51,"end":55.34,"text":"The smaller pieces might be as tiny as a bit of paint,","coverage":1},{"start":56.04,"end":60.08,"text":"but most of them are larger than ten cm across.","coverage":1},{"start":60.88,"end":63.18,"text":"These are parts of old spacecraft,","coverage":1},{"start":63.9,"end":65.28,"text":"broken pieces of satellites,","coverage":1},{"start":65.8,"end":66.7,"text":"and other things.","coverage":1},{"start":67.48,"end":70.72,"text":"Some of this happened because of accidents in space,","coverage":1},{"start":71.34,"end":74.56,"text":"which can create thousands of pieces of space junk.","coverage":1},{"start":75.72,"end":79.94,"text":"Many people would like to find a solution to space junk if they could.","coverage":1},{"start":81.32,"end":85.9,"text":"Scientists worry that if large pieces of space junk hit each other,","coverage":1},{"start":86.28,"end":91.06,"text":"they would break and there would be more and more broken pieces of space junk.","coverage":1},{"start":92.14,"end":94.1,"text":"When there is too much space junk,","coverage":1},{"start":94.66,"end":98.38,"text":"we won't be able to use the space around the Earth for satellites.","coverage":1},{"start":99.86,"end":103.12,"text":"So what options do we have to solve the problem?","coverage":1},{"start":103.84,"end":105.5,"text":"The British mission,","coverage":1},{"start":105.94,"end":106.88,"text":"Remove Debris,","coverage":1},{"start":107.24,"end":112.08,"text":"is trying to solve the problem by catching space junk and taking it away.","coverage":1},{"start":112.88,"end":114.78,"text":"If all the space junk was gone,","coverage":1},{"start":115.18,"end":116.88,"text":"there wouldn't be a problem anymore.","coverage":1},{"start":118.26,"end":121.44,"text":"But what about space junk falling from space?","coverage":1},{"start":122.34,"end":124.3,"text":"What is the danger to people?","coverage":1},{"start":125.52,"end":130.32,"text":"There's not much chance anything would hit you if you were outside on a normal day.","coverage":1},{"start":130.84,"end":134.78,"text":"That's because most junk burns as it falls to Earth.","coverage":1},{"start":135.74,"end":136.96,"text":"In 1997,","coverage":1},{"start":137.68,"end":141.7,"text":"one person in the US was hit by a piece of space junk,","coverage":1},{"start":142.2,"end":143.9,"text":"and she was not hurt at all.","coverage":1},{"start":145.06,"end":146.22,"text":"In 2022,","coverage":1},{"start":147.04,"end":156.54,"text":"a large piece of space junk from a SpaceX spacecraft fell to the surface of the Earth and landed on an Australian sheep farm.","coverage":1},{"start":157.54,"end":159.08,"text":"From time to time,","coverage":1},{"start":159.52,"end":161.48,"text":"other large pieces hit the ground,","coverage":1},{"start":162.04,"end":163.72,"text":"usually in rural areas.","coverage":1},{"start":164.84,"end":165.58,"text":"These days,","coverage":1},{"start":165.98,"end":172.34,"text":"most space agencies work to make their old spacecraft fall in the ocean if possible.","coverage":1},{"start":173.26,"end":173.78,"text":"However,","coverage":1},{"start":174.16,"end":177.24,"text":"with tens of thousands of pieces of space junk,","coverage":1},{"start":177.96,"end":181.7,"text":"there might be more than rain falling from the sky.","coverage":1}],"file":"753e239c51dbf395ecfa.js","track":0,"media":"../assets/media/8b6f885fff8f106631459efc6bce687b7fc6c80b2d00bdda398625b3efb920d2.mp3"}],"../assets/media/8071bb8bb33c484be3ac8cac48856516092018bee709db831f85dc24305e73da.mp3":[{"id":"PPT_8071bb8bb33c484b","audioId":"PPT_8071bb8bb33c484b","title":"Book 2 · Unit 8 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 96","duration":332.49,"cues":[{"start":0,"end":2,"text":"eight .six","coverage":1},{"start":3.48,"end":16.58,"text":"Part two Let me ask Dr Wu to start us off by giving us a little information about the impact of space exploration and the importance of spending money on it.","coverage":1},{"start":17.18,"end":18.58,"text":"Thanks for having me.","coverage":1},{"start":19.04,"end":21.18,"text":"Well, to answer your question,","coverage":1},{"start":22.04,"end":29.56,"text":"space exploration is important because we do research and get information about many things.","coverage":1},{"start":30.3,"end":31.06,"text":"For example,","coverage":1},{"start":31.7,"end":33.9,"text":"as scientists explore space,","coverage":1},{"start":34.48,"end":39,"text":"we learn about biology and about physics as well as space.","coverage":1},{"start":39.86,"end":40.98,"text":"So for me,","coverage":1},{"start":41.42,"end":47.32,"text":"the most important thing is that governments give enough money for future exploration.","coverage":1},{"start":47.92,"end":54.84,"text":"You have a point that space exploration is used for a lot of scientific study,","coverage":1},{"start":55.4,"end":62.22,"text":"but it is very expensive and there is less public money to pay for it nowadays.","coverage":1},{"start":63.08,"end":69.1,"text":"Is having the government pay really the only option for paying for space exploration?","coverage":1},{"start":70.02,"end":72.02,"text":"I hear what you're saying, Dorota.","coverage":1},{"start":72.48,"end":75.4,"text":"It isn't cheap to run space programs,","coverage":1},{"start":76.06,"end":79.72,"text":"but the money we spend is certainly worth it.","coverage":1},{"start":80.36,"end":83.3,"text":"Government and public money must be included.","coverage":1},{"start":84.42,"end":85.24,"text":"So far,","coverage":1},{"start":85.78,"end":90.7,"text":"space exploration has shown us many things about how space works,","coverage":1},{"start":91.22,"end":92.58,"text":"what stars do,","coverage":1},{"start":93.18,"end":98.34,"text":"the effects on people who stay in space for a long time and so on.","coverage":1},{"start":99,"end":106.86,"text":"We must continue to do this work so that we can explore places in space farther away and...","coverage":1},{"start":106.86,"end":108.84,"text":"Can I just say something here?","coverage":1},{"start":109.12,"end":109.78,"text":"Yes, Raj.","coverage":1},{"start":110.12,"end":115.92,"text":"I agree 100 % with Dr Wu that we need space exploration,","coverage":1},{"start":116.34,"end":119.8,"text":"but even he says it is very expensive.","coverage":1},{"start":120.54,"end":124.98,"text":"I know that we have to spend money to develop our space programs","coverage":1},{"start":125.49,"end":128.9,"text":"and we need more money than governments have.","coverage":1},{"start":129.66,"end":130.94,"text":"So for me,","coverage":1},{"start":131.54,"end":139,"text":"an alternative would be to bring in thinkers from different industries to discuss different ways to pay.","coverage":1},{"start":139.72,"end":141.9,"text":"If we are exploring space,","coverage":1},{"start":142.46,"end":145.6,"text":"we could have private companies pay for it.","coverage":1},{"start":145.86,"end":148.98,"text":"For me, this is the main reason we...","coverage":1},{"start":148.98,"end":149.42,"text":"But Raj,","coverage":1},{"start":149.94,"end":152.62,"text":"space exploration is so important.","coverage":1},{"start":153.1,"end":154.18,"text":"Governments must...","coverage":1},{"start":154.18,"end":156.98,"text":"Sorry, Dr Wu, can I finish my point?","coverage":1},{"start":157.7,"end":161.56,"text":"If so much money is spent on space exploration,","coverage":1},{"start":162.14,"end":167.48,"text":"the most important thing should be finding money from places other than the government.","coverage":1},{"start":168.22,"end":171.42,"text":"It shouldn't be just taxpayers paying for it.","coverage":1},{"start":172.2,"end":177.78,"text":"Private companies make lots of money from the discoveries made in space exploration,","coverage":1},{"start":178.16,"end":180.5,"text":"so they should pay for the costs.","coverage":1},{"start":180.5,"end":181.28,"text":"Dorota,","coverage":1},{"start":182.06,"end":183.64,"text":"you haven't said much so far.","coverage":1},{"start":183.86,"end":184.58,"text":"Any thoughts?","coverage":1},{"start":185.1,"end":188.44,"text":"Well, I personally don't see a problem.","coverage":1},{"start":189.12,"end":193.54,"text":"Dr Wu has a good point about public government money,","coverage":1},{"start":193.86,"end":198.82,"text":"and I feel exactly the same as Raj about private money.","coverage":1},{"start":199.42,"end":202.14,"text":"But we can do both of these things.","coverage":1},{"start":202.14,"end":210.52,"text":"Public or government money helps us keep the people who know the most, like those at NASA,","coverage":1},{"start":211.48,"end":212.86,"text":"focused on the research,","coverage":1},{"start":213.54,"end":221.72,"text":"and private money helps bring in other talent from companies that would also like to explore space,","coverage":1},{"start":222.34,"end":226.22,"text":"such as Virgin Galactic or SpaceX.","coverage":1},{"start":227.02,"end":233.44,"text":"Companies like these have already spent a lot of money on this important type of travel.","coverage":1},{"start":233.76,"end":234.02,"text":"Yeah,","coverage":1},{"start":234.56,"end":237.64,"text":"important space travel that governments should...","coverage":1},{"start":237.64,"end":239.8,"text":"Please, allow me to finish.","coverage":1},{"start":241,"end":246.12,"text":"There are also other choices that neither of you have talked about yet.","coverage":1},{"start":246.92,"end":249.94,"text":"Space exploration benefits the world.","coverage":1},{"start":250.7,"end":253.58,"text":"What about money from private individuals?","coverage":1},{"start":253.58,"end":261.46,"text":"There are wealthy people around the world that might be interested in giving money for these projects.","coverage":1},{"start":262.66,"end":263.06,"text":"Also,","coverage":1},{"start":263.5,"end":264.58,"text":"with the internet,","coverage":1},{"start":265.24,"end":269.12,"text":"people from around the world could give money for these projects.","coverage":1},{"start":269.78,"end":274.66,"text":"Lots of people could make donations directly to their favourite projects.","coverage":1},{"start":275.6,"end":281.94,"text":"I think in the future we can get money for space exploration from more than one place.","coverage":1},{"start":282.46,"end":287.16,"text":"We should study these different ways and use the best solution.","coverage":1},{"start":288.58,"end":290.14,"text":"Dr Wu, Raj Paddow,","coverage":1},{"start":290.44,"end":292.26,"text":"let's get your thoughts on this.","coverage":1},{"start":292.72,"end":296.94,"text":"Do you agree with these ideas for paying for space exploration?","coverage":1},{"start":297.94,"end":298.5,"text":"Yes,","coverage":1},{"start":299,"end":300.3,"text":"Dorotta could be right.","coverage":1},{"start":300.98,"end":304.96,"text":"Space exploration needs money to come from many places,","coverage":1},{"start":305.46,"end":310.38,"text":"as long as the government is still a part of this important area of exploration.","coverage":1},{"start":310.38,"end":313.5,"text":"And I think she might be right too,","coverage":1},{"start":313.82,"end":315.06,"text":"but as I said,","coverage":1},{"start":315.48,"end":318.6,"text":"only if there is money from private companies too.","coverage":1},{"start":319,"end":321.66,"text":"Okay, so you have some agreement here then.","coverage":1},{"start":322.32,"end":328.2,"text":"Let's go back to the benefits of space exploration and think about that a little more.","coverage":1},{"start":329.04,"end":330.88,"text":"So does anybody want to...","coverage":1}],"file":"9daa3b8da515483b081b.js","track":0,"media":"../assets/media/8071bb8bb33c484be3ac8cac48856516092018bee709db831f85dc24305e73da.mp3"}],"../assets/media/868d5ca24bd0165d34b0b00151b07d603ddb24e5772fd02ac56395255f978e56.mp3":[{"id":"PPT_868d5ca24bd0165d","audioId":"PPT_868d5ca24bd0165d","title":"Book 2 · Unit 8 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 36","duration":53.94,"cues":[{"start":0,"end":2,"text":"eight .two","coverage":1},{"start":3.74,"end":4.56,"text":"one.","coverage":1},{"start":4.56,"end":8.08,"text":"When the sun is out, we can't see the stars.","coverage":1},{"start":10.02,"end":10.84,"text":"two.","coverage":1},{"start":11.78,"end":16.52,"text":"Another name for Mars is the red planet because of its colour.","coverage":1},{"start":18.48,"end":19.3,"text":"three.","coverage":1},{"start":20.3,"end":21.98,"text":"Whether or not we like it,","coverage":1},{"start":22.38,"end":25.72,"text":"governments spend lots of money on space exploration.","coverage":1},{"start":27.7,"end":28.4,"text":"four.","coverage":1},{"start":29.54,"end":35.22,"text":"People who first travelled in space ate dried food that they added water to.","coverage":1},{"start":37.16,"end":37.86,"text":"five.","coverage":1},{"start":38.76,"end":43.08,"text":"When there are many bright lights at night, it's hard to see the stars.","coverage":1},{"start":45.28,"end":45.98,"text":"six.","coverage":1},{"start":46.96,"end":51.98,"text":"It takes more than an hour for light from the sun to reach the planet Saturn.","coverage":1}],"file":"bc7093eab0a06a3c9e54.js","track":0,"media":"../assets/media/868d5ca24bd0165d34b0b00151b07d603ddb24e5772fd02ac56395255f978e56.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 What things about space do you want to know more about?Possible answer: I want to know whether there is life on other planets.","slide":4,"shape":"16","bookPage":"170"},{"text":"2 How do scientists study space?Possible answer: Scientists use telescopes, satellites and spacecraft to study space.","slide":4,"shape":"18","bookPage":"170"},{"text":"3 What are some things that people invented to use in space?Possible answer: Special food and pens have been designed for use in space.","slide":4,"shape":"6","bookPage":"170"},{"text":"A predictionThe video may discuss weather satellites, space travel and the possibility of livingon Mars.","slide":6,"shape":"19","bookPage":"170"},{"text":"1  Scientists do research to discover new information.","slide":13,"shape":"8","bookPage":"170"},{"text":"2  A telescope is an instrument for looking at distant things.","slide":13,"shape":"9","bookPage":"170"},{"text":"3  We can use GPS to find our location.","slide":13,"shape":"10","bookPage":"170"},{"text":"4  Scientists send robots to explore other planets.","slide":13,"shape":"11","bookPage":"170"},{"text":"5  A satellite is an object in space.","slide":13,"shape":"12","bookPage":"170"},{"text":"1 This video is about space and …Answer: b. how sending things into space can help us.","slide":17,"shape":"16","bookPage":"170"},{"text":"2 Weather satellites …Answer: a. can see large areas of the Earth to look for dangerous weather.","slide":17,"shape":"18","bookPage":"170"},{"text":"3 Space research is important because …Answer: b. if we understand space, our future lives may be better.","slide":17,"shape":"6","bookPage":"170"},{"text":"1 Humans began exploring space in the 1950s.","slide":19,"shape":"16","bookPage":"171"},{"text":"2 Weather satellites help people prepare for dangerous weather.","slide":19,"shape":"18","bookPage":"171"},{"text":"3 Some satellites travel at 3 kilometres per second.","slide":19,"shape":"6","bookPage":"171"},{"text":"4 GPS works when a car and a satellite compare their location and time.","slide":19,"shape":"8","bookPage":"171"},{"text":"5 Solar panels were first made for use in space.","slide":20,"shape":"16","bookPage":"171"},{"text":"6 Scientists study weather and rocks on Mars.","slide":20,"shape":"18","bookPage":"171"},{"text":"1 How did people learn about space before it was possible to send things into space?Possible answer: People watched the night sky and used telescopes.","slide":23,"shape":"16","bookPage":"171"},{"text":"2 Do you agree that understanding space is important for our future? Why / Why not?Possible answer: Yes. It can help us understand weather and changes on Earth.","slide":23,"shape":"18","bookPage":"171"},{"text":"3 What questions would you ask a space scientist?Possible answer: I would ask whether people could ever live on another planet.","slide":24,"shape":"17","bookPage":"171"},{"text":"Being kindKind people may help each other solve problems.","slide":26,"shape":"13","bookPage":"171"},{"text":"Advanced educationA team needs people who understand complex equipment and research.","slide":26,"shape":"15","bookPage":"171"},{"text":"Organizational skillsPeople need to plan and share the many jobs.","slide":26,"shape":"6","bookPage":"171"},{"text":"Special skillsPractical skills may help people repair things or make what they need.","slide":27,"shape":"16","bookPage":"171"},{"text":"InterestsGrowing plants and cooking could help the group live well together.","slide":27,"shape":"18","bookPage":"171"},{"text":"We put organizational skills first because the team has many jobs to finish. The othergroup chose being kind because people need to help one another. We agree that bothqualities are important, even though our rankings differ.","slide":29,"shape":"9","bookPage":"171"},{"text":"The same pronunciationThe words have the same pronunciation, but different spellings and meanings.","slide":33,"shape":"12","bookPage":"172"},{"text":"We can use the meaning of the sentence and the word’s grammatical role. In ‘My son isfour years old’, son means a child and four gives his age. The other spellings, sun andfor, would not fit.","slide":35,"shape":"9","bookPage":"172"},{"text":"When the sun is out, we can’t see the stars.","slide":37,"shape":"17","bookPage":"172"},{"text":"Another name for Mars is the Red Planet because of its colour.","slide":37,"shape":"19","bookPage":"172"},{"text":"Whether or not we like it, governments spend lots of money on space exploration.","slide":37,"shape":"6","bookPage":"172"},{"text":"People who first travelled in space ate dried food that they added water to.","slide":37,"shape":"8","bookPage":"172"},{"text":"When there are many bright lights at night, it’s hard to see the stars.","slide":38,"shape":"17","bookPage":"172"},{"text":"It takes more than an hour for light from the sun to reach Saturn.","slide":38,"shape":"19","bookPage":"172"},{"text":"1 I like the scent of roses.","slide":41,"shape":"12","bookPage":"173"},{"text":"2 I sent my cousin a birthday card.","slide":41,"shape":"14","bookPage":"173"},{"text":"3 I read the comic book you told me about.","slide":41,"shape":"6","bookPage":"173"},{"text":"4 My shoes are red.","slide":41,"shape":"8","bookPage":"173"},{"text":"explore / beyond / journeysExplore means travel around to learn about a place. Beyond means on the otherside. Journeys are long trips.","slide":58,"shape":"15","bookPage":"173"},{"text":"satellites / surface / planetsSatellites send and receive information. Surface means the outside part. Planetsmove around a star.","slide":58,"shape":"17","bookPage":"173"},{"text":"spacecraftSpacecraft are vehicles that travel into space.","slide":59,"shape":"16","bookPage":"173"},{"text":"Do you want to travel in a spacecraft to see the Earth from space? Why / Why not?","slide":61,"shape":"12","bookPage":"174"},{"text":"Do you think humans will ever make a journey to other stars? Why / Why not?","slide":61,"shape":"14","bookPage":"174"},{"text":"What is something you know about another planet, other than Earth?","slide":61,"shape":"6","bookPage":"174"},{"text":"Which planets and parts of space should humans explore? Why?","slide":61,"shape":"8","bookPage":"174"},{"text":"About 70% of the surface of the Earth is water. Do you think we should explore this area more, or is it more important to learn about space?","slide":62,"shape":"16","bookPage":"174"},{"text":"1  What does this podcast normally discuss? Going into space / space journeys","slide":64,"shape":"7","bookPage":"174"},{"text":"2  What type of space junk is mentioned? Satellites / parts of the Sputnik satellites that stopped working","slide":64,"shape":"8","bookPage":"174"},{"text":"3  What are the main problems with space junk? Space junk affects space programmes and causes space accidents","slide":64,"shape":"9","bookPage":"174"},{"text":"Complete the outline: problems, solutions, and dangers of space junk.Problems: fast-moving debris can collide with spacecraft.Solutions: track and remove debris.Dangers on Earth: most burns up; agencies aim for the ocean.","slide":69,"shape":"15","bookPage":"174"},{"text":"A  Travels extremely (1) fast, 25,000 km per hour","slide":70,"shape":"8","bookPage":"174"},{"text":"1  NASA (2) watches where it is","slide":70,"shape":"9","bookPage":"174"},{"text":"2  ISS can move if they get a message 5 (3) hours before","slide":70,"shape":"10","bookPage":"174"},{"text":"2  Parts of old (4) spacecraft, satellites","slide":70,"shape":"13","bookPage":"174"},{"text":"A  Need solution: more accidents = more junk = difficult to use (5) space for satellites","slide":71,"shape":"8","bookPage":"174"},{"text":"B  British RemoveDEBRIS trying to (6) solve problem, catch space junk","slide":71,"shape":"9","bookPage":"174"},{"text":"1  Not much chance of getting (7) hit","slide":72,"shape":"8","bookPage":"174"},{"text":"2  Most space junk burns when it (8) falls","slide":72,"shape":"9","bookPage":"174"},{"text":"3  (9) one person hit, but not hurt","slide":72,"shape":"10","bookPage":"174"},{"text":"5  Space agencies try to get space junk to fall in (10) ocean","slide":72,"shape":"12","bookPage":"174"},{"text":"1 Some pieces are as small as a bit of paint; accidents can create thousands of pieces.","slide":75,"shape":"15","bookPage":"175"},{"text":"2 A large piece from a SpaceX spacecraft landed on an Australian sheep farm in 2022.","slide":75,"shape":"17","bookPage":"175"},{"text":"1. Pieces of space junk can travel at over 25,000 kilometres per hour.","slide":78,"shape":"5","bookPage":null},{"text":"11. Why can space junk cause serious problems?\nA. It changes direction without warning.\nB. It becomes larger as it travels.\nC. It moves at extremely high speeds.","slide":78,"shape":"8","bookPage":null},{"text":"a  controlled by a person or a company and not by the government private","slide":89,"shape":"6","bookPage":"179"},{"text":"b  open to everybody to see or use public","slide":89,"shape":"7","bookPage":"179"},{"text":"c  a person who has a lot of knowledge about something expert","slide":89,"shape":"8","bookPage":"179"},{"text":"d  a natural ability to do something talent","slide":89,"shape":"9","bookPage":"179"},{"text":"e  to consider or study something carefully to decide how good or bad it is evaluate","slide":89,"shape":"10","bookPage":"179"},{"text":"Find the four incorrect words in the poster.We will look at how to pay for Mars exploration.We will evaluate whether the time we spend is worth it.Dorota Loy — a scientist from the Space Development Project.Dr Jun Wu — a lecturer of astrophysics.","slide":93,"shape":"18","bookPage":"179"},{"text":"What are the main issues that the speakers will discuss?a The benefits of space exploration.b How to pay for space exploration.","slide":93,"shape":"19","bookPage":"179"},{"text":"We will look at how to pay for space exploration. We will also evaluate the benefits ofspace exploration and whether the money we spend is worth it.","slide":95,"shape":"9","bookPage":"179"},{"text":"Dorota Loy – an engineer from the Space Development Project","slide":96,"shape":"8","bookPage":"179"},{"text":"Dr Jun Wu – a professor of astrophysics","slide":96,"shape":"10","bookPage":"179"},{"text":"1 Dr Jun WuAnswer: Governments should pay.","slide":98,"shape":"17","bookPage":"180"},{"text":"2 Dorota LoyAnswer: Private individuals could pay.","slide":98,"shape":"19","bookPage":"180"},{"text":"3 Raj PadowAnswer: Private companies could pay.","slide":98,"shape":"6","bookPage":"180"},{"text":"Dorota Loy: Space is expensive, less government money now. Is government money theonly (1) option?","slide":103,"shape":"9","bookPage":"180"},{"text":"Dr Jun Wu: Money we spend is worth it. Have learned about: how space works, whatstars do, (2) effects on people in space.","slide":103,"shape":"10","bookPage":"180"},{"text":"Raj Padow: Need to explore space. But need more than government money. (3) Privatecompanies make money from space exploration, so they should pay.","slide":104,"shape":"7","bookPage":"180"},{"text":"Dorota Loy: Use (4) public money to keep people like NASA focused on research.Private money brings talent from private companies that want to go to space.","slide":104,"shape":"8","bookPage":"180"},{"text":"Other choices: Money from private wealthy people. People could give money to favouriteprojects on the (5) internet. Study what to do.","slide":105,"shape":"7","bookPage":"180"},{"text":"Asking for opinionsYou haven’t said much. Any thoughts? / Let’s get your thoughts on this. / Do youagree with these ideas?","slide":109,"shape":"14","bookPage":"181"},{"text":"Giving opinionsFor me, … / I agree … / I think she might be right. / I feel exactly the same.","slide":109,"shape":"16","bookPage":"181"},{"text":"Acknowledging another viewYou have a point … / I hear what you’re saying, but … / You could be right.","slide":110,"shape":"14","bookPage":"181"},{"text":"Keeping or taking a turnCan I just say something here? / Can I finish my point? / Please allow me to finish.","slide":110,"shape":"16","bookPage":"181"},{"text":"Host: Welcome to our discussion about living on Mars. Raj, why don’t you start us off?","slide":113,"shape":"11","bookPage":"181"},{"text":"Raj: We should explore this option because some places on Earth are becoming harderto live in. We could develop technology for a settlement on Mars.","slide":113,"shape":"13","bookPage":"181"},{"text":"Host: Thank you. Dr Wu, what is your opinion?","slide":113,"shape":"6","bookPage":"181"},{"text":"Dr Wu: Raj has a point about studying other places, but Mars would be very difficult forhumans. I’m not sure people could get used to the conditions.","slide":114,"shape":"10","bookPage":"181"},{"text":"Host: Dorota, we haven’t heard from you. What do you think?","slide":114,"shape":"12","bookPage":"181"},{"text":"Dorota: I hear what you’re saying, but travel to Mars and building a settlement would costa lot. I think we should also use technology to solve problems on Earth.","slide":114,"shape":"6","bookPage":"181"},{"text":"Host: You have raised different options. Which one should we investigate first?","slide":115,"shape":"11","bookPage":"181"},{"text":"impact / effectBoth describe a change or result caused by something.","slide":127,"shape":"12","bookPage":"176"},{"text":"option / alternativeBoth refer to possible choices.","slide":127,"shape":"14","bookPage":"176"},{"text":"problem / issueBoth can refer to a difficulty, but issue can also mean a topic for discussion.","slide":127,"shape":"6","bookPage":"176"},{"text":"solutionA solution is an answer to a problem.","slide":129,"shape":"13","bookPage":"176"},{"text":"1  Why do you think there are issues / problems with building spaceports in places with extreme\nweather or very bad storms, like hurricanes?","slide":131,"shape":"6","bookPage":"176"},{"text":"2  Do you think researchers need to study the effects / impacts and possible problems of\nspaceports before building them? Why / Why not?","slide":131,"shape":"7","bookPage":"176"},{"text":"3  Which alternative / option do you prefer: build spaceports far from people’s homes or don’t build\nany new spaceports? Why?","slide":131,"shape":"8","bookPage":"176"},{"text":"4  What do you think about different countries sharing their spaceports? Do you think this\ncould be a good solution / option?","slide":131,"shape":"9","bookPage":"176"},{"text":"I wrote impacts for Question 2 because the question asks what building a spaceportmight change. Effects also fits, so both answers are possible.","slide":133,"shape":"9","bookPage":"177"},{"text":"1 Why do you think there are issues / problems with building spaceports in places with extreme weather or very bad storms, like hurricanes?Possible answer: Storms could damage equipment and stop flights.","slide":136,"shape":"13","bookPage":"177"},{"text":"2 Do you think researchers need to study the effects / impacts and possible problems of spaceports before building them? Why / Why not?Possible answer: Yes. Researchers should study effects on local people and the environment.","slide":136,"shape":"14","bookPage":"177"},{"text":"3 Which alternative / option do you prefer: build spaceports far from people’s homes or don’t build any new spaceports? Why?Possible answer: I would prefer spaceports far from homes because of the noise.","slide":136,"shape":"15","bookPage":"177"},{"text":"4 What do you think about different countries sharing their spaceports? Do you think this could be a good solution / option?Possible answer: Sharing may reduce costs, but countries would need to agree on how to use the spaceport.","slide":137,"shape":"14","bookPage":"177"},{"text":"1 If the telescope were cheaper, our club would buy it.","slide":143,"shape":"13","bookPage":"177"},{"text":"2 We could visit Mars if we had a very fast spacecraft.","slide":143,"shape":"15","bookPage":"177"},{"text":"3 If she worked for a space programme, she could design robots.","slide":144,"shape":"13","bookPage":"177"},{"text":"4 I would ask an expert if I had a question.","slide":144,"shape":"15","bookPage":"177"},{"text":"1 If I became an astronaut, I could go to the moon.","slide":147,"shape":"12","bookPage":"178"},{"text":"2 If I found a piece of space junk, I wouldn’t know what to do.","slide":147,"shape":"13","bookPage":"178"},{"text":"3 I would visit space as a tourist if I were rich.","slide":147,"shape":"14","bookPage":"178"},{"text":"4 If I had a very fast spacecraft, I would / could travel to Saturn.","slide":148,"shape":"15","bookPage":"178"},{"text":"5 If I weren’t ill, I would go to my classes.","slide":148,"shape":"16","bookPage":"178"},{"text":"6 Taylor would / could study Engineering if she wanted to design spacecraft.","slide":148,"shape":"17","bookPage":"178"},{"text":"7 People would understand the importance of space research if the government explained it.","slide":149,"shape":"16","bookPage":"178"},{"text":"8 If wealthy people gave a lot of money to the project, the government could / would build a new spaceport.","slide":149,"shape":"17","bookPage":"178"},{"text":"1 What would you do if a space programme invited you to join as a researcher?Possible answer: If I were invited, I would say yes because I would like to see Earth from space.","slide":151,"shape":"16","bookPage":"178"},{"text":"2 What would you do if a company planned to build a large spaceport near your home?Possible answer: If a company planned a spaceport near my home, I would ask about noise andsafety.","slide":151,"shape":"18","bookPage":"178"},{"text":"3 What would you do if you saw a spacecraft that did not look like it was from Earth?Possible answer: If I saw an unusual spacecraft, I would contact the authorities.","slide":152,"shape":"16","bookPage":"178"},{"text":"4 What type of robots would you design if you worked for a space programme?Possible answer: If I worked for a space programme, I would design robots to repair satellites.","slide":152,"shape":"18","bookPage":"178"},{"text":"5 Write another second-conditional question.Possible question: What would you do if you owned a space company?","slide":153,"shape":"16","bookPage":"178"},{"text":"6 Write another second-conditional question.Possible question: What would you do if you found a piece of space junk?","slide":153,"shape":"18","bookPage":"178"},{"text":"We need a solution to this problem.","slide":159,"shape":"6","bookPage":null},{"text":"An expert could help us understand the equipment.","slide":159,"shape":"9","bookPage":null},{"text":"We had a difficulty at the viewing session. Clouds covered the sky. Because of those clouds, we could not see the stars. We decided to try again on another evening.","slide":160,"shape":"6","bookPage":null},{"text":"I would ask someone before using it. Our group has a new telescope. Nobody in the group knows how to set it up. An expert could show us how.","slide":161,"shape":"6","bookPage":null},{"text":"A young person is using a telescope outdoors. The telescope points towards the night sky.","slide":162,"shape":"7","bookPage":null},{"text":"If I joined the activity, I would ask an expert how to use the telescope. I would like to explore the night sky.","slide":162,"shape":"10","bookPage":null},{"text":"1. With enough warning, the ISS can move away from approaching junk.","slide":167,"shape":"5","bookPage":null},{"text":"11. Why has the amount of space junk grown?\nA. Space missions are leaving Earth at higher speeds.\nB. People continue sending many things into space.\nC. The ISS has stopped moving away from dangerous objects.","slide":167,"shape":"8","bookPage":null},{"text":"1. Space junk can travel at over 25,000 kilometres per hour.\nAnswer: TRUE","slide":170,"shape":"5","bookPage":null},{"text":"11. The 2022 SpaceX piece landed on an Australian sheep farm.\nAnswer: TRUE","slide":170,"shape":"8","bookPage":null},{"text":"We could evaluate two possible solutions.","slide":178,"shape":"6","bookPage":null},{"text":"The new plan offers an alternative to the trip.","slide":178,"shape":"9","bookPage":null},{"text":"Sharing the equipment needs a little planning. Eight students want to use one telescope. That number would make an open queue slow. Short booking slots could give each student a turn.","slide":179,"shape":"6","bookPage":null},{"text":"The nearest exhibition is still some distance away. The group could travel there by train. However, the train tickets would use most of the budget. An online tour would be a cheaper alternative.","slide":180,"shape":"6","bookPage":null},{"text":"A man is adjusting a telescope beside an observatory. He may be preparing a viewing session. If visitors arrived, he could explain the equipment.","slide":181,"shape":"7","bookPage":null},{"text":"If clouds blocked the sky, the group could visit the observatory building. An expert could explain how the equipment works. This alternative would still help beginners learn.","slide":182,"shape":"7","bookPage":null},{"text":"The problemSpace exploration can be very expensive. Should government or private moneypay for it?","slide":208,"shape":"10","bookPage":"183"},{"text":"Problem\nPossible solution\nSpace exploration is expensive.\n\nWho should pay?\nUse government money and taxes.\n\nFind money from private companies.\n\nUse both private and public money.\n\nFind money from wealthy individuals.","slide":210,"shape":"12","bookPage":"183"},{"text":"I think combining public and private money is best. Public funding can support long-termresearch, while companies can bring other skills and resources. The partners would needclear agreements about their responsibilities.","slide":212,"shape":"9","bookPage":"183"},{"text":"Children get\nbored easily.","slide":215,"shape":"15","bookPage":"184"},{"text":"They think they\nalready know a\nlot.","slide":215,"shape":"17","bookPage":"184"},{"text":"Some children\nare afraid of\nspace.","slide":215,"shape":"19","bookPage":"184"},{"text":"City lights hide\nthe stars at night.","slide":215,"shape":"21","bookPage":"184"},{"text":"No local place\nto learn about\nspace.","slide":215,"shape":"23","bookPage":"184"},{"text":"Equipment can\nbe expensive.","slide":215,"shape":"25","bookPage":"184"},{"text":"I think the most serious problem is that children get bored easily. If we cannot get theirinterest, they will not want to learn. We need activities that make them curious and letthem take part.","slide":217,"shape":"9","bookPage":"184"},{"text":"Problem\nPossible solution\nIt is hard to see stars in the city.\nArrange a trip outside the city.\n\nLearn about stars that can still be seen.\n\nVisit a planetarium.\n\nUse suitable telescope images.","slide":220,"shape":"12","bookPage":"184"},{"text":"Problem\nPossible solution\nChildren might get bored.\nShow exciting clips about space.\n\nDiscuss interesting space projects.\n\nVisit a space museum.\n\nMake space models.","slide":221,"shape":"12","bookPage":"184"},{"text":"Problem\nPossible solution\nTelescopes are expensive.\nVisit a place that has a telescope.\n\nInvite someone with a telescope.\n\nAsk another school to share equipment.\n\nUse NASA telescope images.","slide":222,"shape":"12","bookPage":"184"},{"text":"Problem\nPossible solution\nExperts live far away.\nPlan a trip to hear a talk.\n\nAsk a university about a school visit.\n\nVisit an observatory.\n\nLook for expert talks online.","slide":223,"shape":"12","bookPage":"184"},{"text":"1 Can you think of any other ways to organize your ideas about problems and solutions? Look back at the different tables in the units of the book to help you.Possible answer: Use an ideas map or a table comparing advantages, disadvantages and costs.","slide":227,"shape":"14","bookPage":"185"},{"text":"2 What kind of information can you give to support your ideas for possible solutions? Think of supporting ideas you can add to the table in Exercise 6 to help you.Possible answer: Add examples, likely costs, resources needed and reasons the activity wouldinterest children.","slide":228,"shape":"14","bookPage":"185"},{"text":"Inviting somebody\nelse to speak\nInterrupting\nContinuing to speak\na  What is your opinion?f  You haven’t said much. What do you think?g  Why don’t you start us off …?i  Would anybody like to say anything else about …?\nd  Could I just say something?e  Sorry, but I have to interrupt you and say …h  Sorry, but can I just say …?\nb  Could I finish?c  I’d like to finish my point.j  Let me just finish what I was saying.","slide":233,"shape":"12","bookPage":"185"},{"text":"Halil: We are discussing the best way to travel. (1) Why don’t you start us off, Ramona?","slide":235,"shape":"16","bookPage":"186"},{"text":"Shin: (2) Could I just say something? Doesn’t that depend on the train? In many cities, you can’t sit down. Trains are too crowded and …","slide":235,"shape":"18","bookPage":"186"},{"text":"Ramona: (3) Let me just finish what I was saying. You can relax and watch the world go by, but that’s in a city where the trains are not too busy.","slide":235,"shape":"5","bookPage":"186"},{"text":"Halil: (4) Would anybody like to say anything else about trains?","slide":235,"shape":"6","bookPage":"186"},{"text":"Halil: And Roberto, (5) you haven’t said much. What do you think? (6) What is your opinion?","slide":236,"shape":"18","bookPage":"186"},{"text":"1 Let me begin by asking … — S — start","slide":243,"shape":"15","bookPage":"186"},{"text":"2 Let me end this by saying … — F — finish","slide":243,"shape":"16","bookPage":"186"},{"text":"3 We’ll begin today’s discussion by … — S — start","slide":243,"shape":"17","bookPage":"186"},{"text":"4 Would you like to start? — S — start","slide":243,"shape":"5","bookPage":"186"},{"text":"5 So, to conclude … — F — finish","slide":243,"shape":"6","bookPage":"186"},{"text":"6 Finally, … — F — finish","slide":243,"shape":"7","bookPage":"186"},{"text":"Carlos: (1) I see your point. (weak) But do you think we really need a lot of kids interested in space?","slide":245,"shape":"17","bookPage":"187"},{"text":"Hao: Hmm. Carlos, (2) I hear what you’re saying, (weak) but Ela has a good point. Even if people don’t work on space exploration, we still need engineers so we have satellites in orbit for our phones and GPS.","slide":245,"shape":"18","bookPage":"187"},{"text":"Ela: (3) I agree with you completely, (strong) Hao. And we have satellites for predicting the weather, too.","slide":245,"shape":"5","bookPage":"187"},{"text":"Carlos: (4) You’re absolutely right. (strong) I don’t want to lose those things. But I don’t think kids need to get interested in living on Mars.","slide":246,"shape":"16","bookPage":"187"},{"text":"Ela: Hmm. (5) You might be right. (weak) Well, who knows what will happen with global warming and our future. Don’t you think it would be good to have some options?","slide":246,"shape":"17","bookPage":"187"},{"text":"Hao: I think both of (6) you have a point. (weak) Still, maybe it is good to at least ensure children know about space exploration.","slide":246,"shape":"18","bookPage":"187"},{"text":"A: My problem was that telescopes are expensive and we don’t have much money. Wecould visit a place with a telescope or invite someone with one. What were your ideas?","slide":254,"shape":"10","bookPage":"188"},{"text":"B: I agree about the problem, but my solutions were different. We could ask anotherschool to share a telescope or use telescope images on the NASA website. What is youropinion?","slide":254,"shape":"12","bookPage":"188"},{"text":"C: I hear what you’re saying, but I chose a different problem. We are in a city, so childrencannot easily see the stars.","slide":255,"shape":"11","bookPage":"188"},{"text":"A: For us, the biggest problem is that we are in a city, so children can’t see the stars.What should we do? What do you think?","slide":261,"shape":"11","bookPage":"188"},{"text":"B: I think we can take the children to a museum. Sometimes there are shows about thenight sky or planets.","slide":261,"shape":"13","bookPage":"188"},{"text":"C: That’s a good idea. We can also ask experts to come to school and talk.","slide":261,"shape":"6","bookPage":"188"},{"text":"A: I’m not sure about that idea because experts are very busy. Maybe teachers shouldjust teach the children. D, you haven’t said much. Let’s get your thoughts on this.","slide":262,"shape":"11","bookPage":"188"},{"text":"D: I agree with the idea of going to museums one hundred percent. But I’m not sureabout using experts. You have a point, but how do we get experts?","slide":262,"shape":"13","bookPage":"188"},{"text":"C: We can just ask them. I know a professor …","slide":262,"shape":"6","bookPage":"188"},{"text":"A: I hear what you’re saying, but …","slide":263,"shape":"11","bookPage":"188"},{"text":"C: Can I finish my point? I know a professor who would be happy to do school visits.","slide":263,"shape":"13","bookPage":"188"},{"text":"A: I see your point. B, what’s your opinion?","slide":263,"shape":"6","bookPage":"188"},{"text":"B: I like the idea of using experts.","slide":263,"shape":"8","bookPage":"188"},{"text":"D: Yes, I think the best idea is asking experts to come to schools.","slide":264,"shape":"11","bookPage":"188"},{"text":"We chose to invite a local expert and use telescope images. This plan would cost littleand let children ask their own questions. A museum visit is also useful, but it would needmore travel time and money.","slide":266,"shape":"9","bookPage":"188"},{"text":"Could I just say something?","slide":270,"shape":"6","bookPage":null},{"text":"Let me finish my point.","slide":270,"shape":"9","bookPage":null},{"text":"I see why you suggested a museum visit. The visit would use our whole budget. That would leave nothing for classroom equipment. An online tour could leave money for useful models.","slide":271,"shape":"6","bookPage":null},{"text":"Let me explain the main difficulty first. Our group has only one telescope. This means everyone needs to wait for a turn. Would a booking timetable make that wait easier to manage?","slide":272,"shape":"6","bookPage":null},{"text":"I see your point about choosing a darker place. It might make the viewing session more useful. However, the group would need to travel there. We should compare transport options before deciding.","slide":273,"shape":"7","bookPage":null},{"text":"Could I suggest another option? We could use clear photographs in the classroom. This would let everyone join without travelling. What do you think about that alternative?","slide":274,"shape":"7","bookPage":null}];
